import React, { useEffect } from "react";
import { navigate, HeadFC } from "gatsby";
import Navbar from "../components/nav";
import Footer from "../components/footer";
import SEO from "../components/seo";

const NotFoundPage: React.FC = () => {
  useEffect(() => {
    if (typeof window !== "undefined") {
      const path = window.location.pathname;
      
      if (path !== '/' && !window.location.search.includes('path=')) {
        console.log('404 redirect for path:', path); // Debug log
        navigate(`/?path=${path}`, { replace: true });
      }
    }
  }, []);

  return (
    <main className="container">
      <Navbar />
      <div className="intro-container">
        <p className="intro">Page not found. Redirecting you to the home page...</p>
      </div>
      <Footer />
    </main>
  );
};

export const Head: HeadFC = () => (
  <SEO 
    title="Page Not Found" 
    description="The page you're looking for doesn't exist."
  />
);

export default NotFoundPage;